CREATE TRIGGER history_purchase_items_insert BEFORE INSERT ON purchase_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('purchase') AND reference_id=NEW.purchase_id AND posting_state='posted') OR (NEW.id!=-1 AND EXISTS(SELECT 1 FROM purchase_items original JOIN ledger_entries e ON e.reference_id=original.purchase_id WHERE original.id=NEW.id AND e.reference_type IN ('purchase') AND e.posting_state='posted')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_purchase_items_update BEFORE UPDATE ON purchase_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('purchase') AND reference_id=OLD.purchase_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('purchase') AND reference_id=NEW.purchase_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM purchase_items original JOIN ledger_entries e ON e.reference_id=original.purchase_id WHERE original.id=NEW.id AND e.reference_type IN ('purchase') AND e.posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
