CREATE TRIGGER history_sale_items_insert BEFORE INSERT ON sale_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale','sale_cogs') AND reference_id=NEW.sale_id AND posting_state='posted') OR (NEW.id!=-1 AND EXISTS(SELECT 1 FROM sale_items original JOIN ledger_entries e ON e.reference_id=original.sale_id WHERE original.id=NEW.id AND e.reference_type IN ('sale','sale_cogs') AND e.posting_state='posted')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_sale_items_update BEFORE UPDATE ON sale_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale','sale_cogs') AND reference_id=OLD.sale_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale','sale_cogs') AND reference_id=NEW.sale_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM sale_items original JOIN ledger_entries e ON e.reference_id=original.sale_id WHERE original.id=NEW.id AND e.reference_type IN ('sale','sale_cogs') AND e.posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
