CREATE TRIGGER history_sale_return_items_insert BEFORE INSERT ON sale_return_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale_return','sale_return_cogs') AND reference_id=NEW.return_id AND posting_state='posted') OR (NEW.id!=-1 AND EXISTS(SELECT 1 FROM sale_return_items original JOIN ledger_entries e ON e.reference_id=original.return_id WHERE original.id=NEW.id AND e.reference_type IN ('sale_return','sale_return_cogs') AND e.posting_state='posted')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_sale_return_items_update BEFORE UPDATE ON sale_return_items WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale_return','sale_return_cogs') AND reference_id=OLD.return_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale_return','sale_return_cogs') AND reference_id=NEW.return_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM sale_return_items original JOIN ledger_entries e ON e.reference_id=original.return_id WHERE original.id=NEW.id AND e.reference_type IN ('sale_return','sale_return_cogs') AND e.posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_sale_returns_delete BEFORE DELETE ON sale_returns WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale_return','sale_return_cogs') AND reference_id=OLD.id AND posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_sale_returns_update BEFORE UPDATE ON sale_returns WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_type IN ('sale_return','sale_return_cogs') AND reference_id=OLD.id AND posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_stock_append BEFORE INSERT ON stock_movements WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE reference_id=NEW.reference_id AND posting_state='posted' AND (reference_type=NEW.reference_type OR (NEW.reference_type='sale' AND reference_type='sale_cogs') OR (NEW.reference_type='sale_return' AND reference_type='sale_return_cogs'))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_stock_movements_delete BEFORE DELETE ON stock_movements WHEN 1 BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_stock_movements_replace BEFORE INSERT ON stock_movements WHEN NEW.id!=-1 AND EXISTS(SELECT 1 FROM stock_movements WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER history_stock_movements_update BEFORE UPDATE ON stock_movements WHEN 1 BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER identity_sentinel_customers AFTER INSERT ON "customers" WHEN NEW.id=-1 BEGIN SELECT RAISE(ABORT,'Reserved implicit identity'); END;
