CREATE TRIGGER ledger_entry_delete BEFORE DELETE ON ledger_entries WHEN OLD.posting_state='posted' BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_entry_identity BEFORE UPDATE OF id ON ledger_entries WHEN NEW.id!=OLD.id AND EXISTS(SELECT 1 FROM ledger_lines WHERE entry_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_entry_insert BEFORE INSERT ON ledger_entries WHEN NEW.posting_state!='draft' OR (NEW.id!=-1 AND EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.id AND posting_state='posted')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_entry_post BEFORE UPDATE OF posting_state ON ledger_entries WHEN NEW.posting_state='posted' AND ((SELECT COUNT(*) FROM ledger_lines WHERE entry_id=OLD.id)<2 OR COALESCE((SELECT SUM(debit_minor) FROM ledger_lines WHERE entry_id=OLD.id),0)<=0 OR (SELECT SUM(debit_minor) FROM ledger_lines WHERE entry_id=OLD.id)!=(SELECT SUM(credit_minor) FROM ledger_lines WHERE entry_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_entry_update BEFORE UPDATE ON ledger_entries WHEN OLD.posting_state='posted' OR EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.id AND posting_state='posted') OR NEW.posting_state NOT IN ('draft','posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_line_delete BEFORE DELETE ON ledger_lines WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE id=OLD.entry_id AND posting_state='posted') BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_line_insert BEFORE INSERT ON ledger_lines WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.entry_id AND posting_state='posted') OR (NEW.id!=-1 AND EXISTS(SELECT 1 FROM ledger_lines l JOIN ledger_entries e ON e.id=l.entry_id WHERE l.id=NEW.id AND e.posting_state='posted')) OR NOT EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.entry_id) OR NEW.account_code NOT IN ('cash','wallet','receivables','payables','inventory','inventory_variance','financial_variance','sales','cogs','expenses','interest_income','capital') OR ((NEW.party_type IS NULL)!=(NEW.party_id IS NULL)) OR (NEW.account_code='receivables' AND (NEW.party_type IS NULL OR NEW.party_type!='customer')) OR (NEW.account_code='payables' AND (NEW.party_type IS NULL OR NEW.party_type!='supplier')) OR (NEW.account_code NOT IN ('receivables','payables') AND NEW.party_type IS NOT NULL) OR (NEW.party_type='customer' AND NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.party_id)) OR (NEW.party_type='supplier' AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.party_id)) OR (NEW.party_type IS NOT NULL AND NEW.party_type NOT IN ('customer','supplier')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_line_update BEFORE UPDATE ON ledger_lines WHEN EXISTS(SELECT 1 FROM ledger_entries WHERE id=OLD.entry_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.entry_id AND posting_state='posted') OR EXISTS(SELECT 1 FROM ledger_lines l JOIN ledger_entries e ON e.id=l.entry_id WHERE l.id=NEW.id AND e.posting_state='posted') OR NOT EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.entry_id) OR NEW.account_code NOT IN ('cash','wallet','receivables','payables','inventory','inventory_variance','financial_variance','sales','cogs','expenses','interest_income','capital') OR ((NEW.party_type IS NULL)!=(NEW.party_id IS NULL)) OR (NEW.account_code='receivables' AND (NEW.party_type IS NULL OR NEW.party_type!='customer')) OR (NEW.account_code='payables' AND (NEW.party_type IS NULL OR NEW.party_type!='supplier')) OR (NEW.account_code NOT IN ('receivables','payables') AND NEW.party_type IS NOT NULL) OR (NEW.party_type='customer' AND NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.party_id)) OR (NEW.party_type='supplier' AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.party_id)) OR (NEW.party_type IS NOT NULL AND NEW.party_type NOT IN ('customer','supplier')) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER ledger_lines_valid_insert
      BEFORE INSERT ON ledger_lines
      WHEN NEW.debit_minor < 0
        OR NEW.credit_minor < 0
        OR (NEW.debit_minor > 0 AND NEW.credit_minor > 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid ledger line values'); END;
CREATE TRIGGER ledger_lines_valid_update
      BEFORE UPDATE OF debit_minor, credit_minor ON ledger_lines
      WHEN NEW.debit_minor < 0
        OR NEW.credit_minor < 0
        OR (NEW.debit_minor > 0 AND NEW.credit_minor > 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid ledger line values'); END;
CREATE TRIGGER migration_baseline_delete BEFORE DELETE ON migration_baselines BEGIN SELECT RAISE(ABORT,'Historical baseline is immutable'); END;
CREATE TRIGGER migration_baseline_replace BEFORE INSERT ON migration_baselines WHEN EXISTS(SELECT 1 FROM migration_baselines WHERE key=NEW.key) BEGIN SELECT RAISE(ABORT,'Historical baseline is immutable'); END;
CREATE TRIGGER migration_baseline_update BEFORE UPDATE ON migration_baselines BEGIN SELECT RAISE(ABORT,'Historical baseline is immutable'); END;
CREATE TRIGGER opening_party_insert BEFORE INSERT ON opening_balances WHEN (NEW.balance_type='customerReceivable' AND NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.party_id)) OR (NEW.balance_type='supplierPayable' AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.party_id)) BEGIN SELECT RAISE(ABORT,'Invalid opening party'); END;
CREATE TRIGGER opening_party_update BEFORE UPDATE ON opening_balances WHEN (NEW.balance_type='customerReceivable' AND NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.party_id)) OR (NEW.balance_type='supplierPayable' AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.party_id)) BEGIN SELECT RAISE(ABORT,'Invalid opening party'); END;
CREATE TRIGGER plan_identity_immutable BEFORE UPDATE ON installment_plans WHEN NEW.owner_type!=OLD.owner_type OR NEW.owner_id!=OLD.owner_id OR NEW.party_type!=OLD.party_type OR NEW.party_id!=OLD.party_id OR NEW.principal_minor!=OLD.principal_minor OR NEW.interest_minor!=OLD.interest_minor OR NEW.installment_count!=OLD.installment_count OR NEW.created_at!=OLD.created_at BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER plan_party_insert BEFORE INSERT ON installment_plans WHEN NOT ((NEW.party_type='customer' AND EXISTS(SELECT 1 FROM customers target WHERE target.id=NEW.party_id)) OR (NEW.party_type='supplier' AND EXISTS(SELECT 1 FROM suppliers target WHERE target.id=NEW.party_id))) OR (NEW.owner_type='sale' AND NOT EXISTS(SELECT 1 FROM sale_invoices WHERE id=NEW.owner_id AND customer_id=NEW.party_id AND NEW.party_type='customer')) OR (NEW.owner_type='purchase' AND NOT EXISTS(SELECT 1 FROM purchase_invoices WHERE id=NEW.owner_id AND supplier_id=NEW.party_id AND NEW.party_type='supplier')) OR (NEW.owner_type='opening_balance' AND NOT EXISTS(SELECT 1 FROM opening_balances WHERE id=NEW.owner_id AND party_id=NEW.party_id AND ((balance_type='customerReceivable' AND NEW.party_type='customer') OR (balance_type='supplierPayable' AND NEW.party_type='supplier')))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER plan_party_update BEFORE UPDATE ON installment_plans WHEN NOT ((NEW.party_type='customer' AND EXISTS(SELECT 1 FROM customers target WHERE target.id=NEW.party_id)) OR (NEW.party_type='supplier' AND EXISTS(SELECT 1 FROM suppliers target WHERE target.id=NEW.party_id))) OR (NEW.owner_type='sale' AND NOT EXISTS(SELECT 1 FROM sale_invoices WHERE id=NEW.owner_id AND customer_id=NEW.party_id AND NEW.party_type='customer')) OR (NEW.owner_type='purchase' AND NOT EXISTS(SELECT 1 FROM purchase_invoices WHERE id=NEW.owner_id AND supplier_id=NEW.party_id AND NEW.party_type='supplier')) OR (NEW.owner_type='opening_balance' AND NOT EXISTS(SELECT 1 FROM opening_balances WHERE id=NEW.owner_id AND party_id=NEW.party_id AND ((balance_type='customerReceivable' AND NEW.party_type='customer') OR (balance_type='supplierPayable' AND NEW.party_type='supplier')))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER products_nonnegative_insert
      BEFORE INSERT ON products
      WHEN NEW.stock_qty < 0
        OR NEW.min_stock_qty < 0
        OR NEW.sale_price_minor <= 0
        OR NEW.avg_cost_minor < 0
        OR NEW.inventory_value_minor < 0
        OR (NEW.stock_qty = 0 AND NEW.inventory_value_minor != 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid product inventory values'); END;
CREATE TRIGGER products_nonnegative_update
      BEFORE UPDATE OF stock_qty, min_stock_qty, sale_price_minor,
          avg_cost_minor, inventory_value_minor ON products
      WHEN NEW.stock_qty < 0
        OR NEW.min_stock_qty < 0
        OR NEW.sale_price_minor <= 0
        OR NEW.avg_cost_minor < 0
        OR NEW.inventory_value_minor < 0
        OR (NEW.stock_qty = 0 AND NEW.inventory_value_minor != 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid product inventory values'); END;
CREATE TRIGGER purchase_items_positive_quantity
      BEFORE INSERT ON purchase_items
      WHEN NEW.qty <= 0
      BEGIN SELECT RAISE(ABORT, 'Purchase item quantity must be positive'); END;
CREATE TRIGGER purchase_return_items_positive_quantity
      BEFORE INSERT ON purchase_return_items
      WHEN NEW.qty <= 0
      BEGIN SELECT RAISE(ABORT, 'Purchase return item quantity must be positive'); END;
CREATE TRIGGER receipt_immutable_delete BEFORE DELETE ON operation_receipts BEGIN SELECT RAISE(ABORT,'Operation receipt is immutable'); END;
CREATE TRIGGER receipt_immutable_replace BEFORE INSERT ON operation_receipts WHEN EXISTS(SELECT 1 FROM operation_receipts WHERE receipt_key=NEW.receipt_key OR (namespace=NEW.namespace AND operation_key=NEW.operation_key)) BEGIN SELECT RAISE(ABORT,'Operation receipt is immutable'); END;
CREATE TRIGGER receipt_immutable_update BEFORE UPDATE ON operation_receipts BEGIN SELECT RAISE(ABORT,'Operation receipt is immutable'); END;
CREATE TRIGGER reference_installment_plans_insert BEFORE INSERT ON installment_plans WHEN NOT ((NEW.owner_type='sale' AND EXISTS(SELECT 1 FROM sale_invoices target WHERE target.id=NEW.owner_id)) OR (NEW.owner_type='purchase' AND EXISTS(SELECT 1 FROM purchase_invoices target WHERE target.id=NEW.owner_id)) OR (NEW.owner_type='opening_balance' AND EXISTS(SELECT 1 FROM opening_balances target WHERE target.id=NEW.owner_id))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER reference_installment_plans_update BEFORE UPDATE ON installment_plans WHEN NOT ((NEW.owner_type='sale' AND EXISTS(SELECT 1 FROM sale_invoices target WHERE target.id=NEW.owner_id)) OR (NEW.owner_type='purchase' AND EXISTS(SELECT 1 FROM purchase_invoices target WHERE target.id=NEW.owner_id)) OR (NEW.owner_type='opening_balance' AND EXISTS(SELECT 1 FROM opening_balances target WHERE target.id=NEW.owner_id))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
