CREATE TRIGGER reference_target_suppliers_replace BEFORE INSERT ON suppliers WHEN NEW.id!=-1 AND ((EXISTS(SELECT 1 FROM ledger_lines WHERE party_type='supplier' AND party_id=NEW.id) OR EXISTS(SELECT 1 FROM installment_plans WHERE party_type='supplier' AND party_id=NEW.id))) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER return_source_purchase_return_items_insert BEFORE INSERT ON purchase_return_items WHEN NOT EXISTS(SELECT 1 FROM purchase_returns h JOIN purchase_items i ON i.purchase_id=h.purchase_id WHERE h.id=NEW.return_id AND i.id=NEW.purchase_item_id AND i.product_id=NEW.product_id) OR NEW.qty > (SELECT qty FROM purchase_items WHERE id=NEW.purchase_item_id) - COALESCE((SELECT SUM(qty) FROM purchase_return_items WHERE purchase_item_id=NEW.purchase_item_id ),0) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER return_source_purchase_return_items_update BEFORE UPDATE ON purchase_return_items WHEN NOT EXISTS(SELECT 1 FROM purchase_returns h JOIN purchase_items i ON i.purchase_id=h.purchase_id WHERE h.id=NEW.return_id AND i.id=NEW.purchase_item_id AND i.product_id=NEW.product_id) OR NEW.qty > (SELECT qty FROM purchase_items WHERE id=NEW.purchase_item_id) - COALESCE((SELECT SUM(qty) FROM purchase_return_items WHERE purchase_item_id=NEW.purchase_item_id AND id!=OLD.id),0) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER return_source_sale_return_items_insert BEFORE INSERT ON sale_return_items WHEN NOT EXISTS(SELECT 1 FROM sale_returns h JOIN sale_items i ON i.sale_id=h.sale_id WHERE h.id=NEW.return_id AND i.id=NEW.sale_item_id AND i.product_id=NEW.product_id) OR NEW.qty > (SELECT qty FROM sale_items WHERE id=NEW.sale_item_id) - COALESCE((SELECT SUM(qty) FROM sale_return_items WHERE sale_item_id=NEW.sale_item_id ),0) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER return_source_sale_return_items_update BEFORE UPDATE ON sale_return_items WHEN NOT EXISTS(SELECT 1 FROM sale_returns h JOIN sale_items i ON i.sale_id=h.sale_id WHERE h.id=NEW.return_id AND i.id=NEW.sale_item_id AND i.product_id=NEW.product_id) OR NEW.qty > (SELECT qty FROM sale_items WHERE id=NEW.sale_item_id) - COALESCE((SELECT SUM(qty) FROM sale_return_items WHERE sale_item_id=NEW.sale_item_id AND id!=OLD.id),0) BEGIN SELECT RAISE(ABORT,'Invalid reference or immutable posted history'); END;
CREATE TRIGGER sale_items_positive_quantity
      BEFORE INSERT ON sale_items
      WHEN NEW.qty <= 0
      BEGIN SELECT RAISE(ABORT, 'Sale item quantity must be positive'); END;
CREATE TRIGGER sale_return_items_positive_quantity
      BEFORE INSERT ON sale_return_items
      WHEN NEW.qty <= 0
      BEGIN SELECT RAISE(ABORT, 'Sale return item quantity must be positive'); END;
CREATE TRIGGER shifts_nonnegative_insert
      BEFORE INSERT ON shifts
      WHEN NEW.opening_cash_minor < 0
        OR (NEW.actual_cash_minor IS NOT NULL AND NEW.actual_cash_minor < 0)
      BEGIN SELECT RAISE(ABORT, 'Shift cash cannot be negative'); END;
CREATE TRIGGER shifts_nonnegative_update
      BEFORE UPDATE OF opening_cash_minor, actual_cash_minor ON shifts
      WHEN NEW.opening_cash_minor < 0
        OR (NEW.actual_cash_minor IS NOT NULL AND NEW.actual_cash_minor < 0)
      BEGIN SELECT RAISE(ABORT, 'Shift cash cannot be negative'); END;
